import torch
from lab3 import precision as P
from lab3.evaln import load_checkpoint
parent,_ = load_checkpoint("gcn",0); parent.eval()
m,_ = P.int8_quantize_static(parent, "gcn")
pw = m.conv1.lin._packed_weight_0
for n in dir(pw):
    if n.startswith('_') and not n.startswith('__'):
        try: print(n, type(getattr(pw,n)).__name__)
        except Exception as e: print(n, "ERR", e)
EOF

