import io, zipfile, torch, json
torch.backends.quantized.engine = "qnnpack"
import warnings; warnings.filterwarnings("ignore")
from lab3 import precision as P
from lab3.evaln import load_checkpoint

parent,_ = load_checkpoint("mlp",0); parent.eval()
dense_q,_ = P.int8_quantize_dynamic(parent, "mlp")
buf = io.BytesIO(); torch.save(dense_q, buf)
m = torch.load(io.BytesIO(buf.getvalue()), weights_only=False)
tot=0
for n,p in m.named_parameters():
    tot += p.numel()*p.element_size()
    print("param",n,p.dtype,tuple(p.shape),p.numel()*p.element_size())
for n,b in m.named_buffers():
    tot += b.numel()*b.element_size()
    print("buffer",n,b.dtype,tuple(b.shape),b.numel()*b.element_size())
print("total named tensor bytes:", tot)
# where do 200704 + 32768 live? walk raw state
sd = m.state_dict()
for k,v in sd.items():
    if torch.is_tensor(v): print("sd tensor", k, v.dtype, tuple(v.shape), v.numel()*v.element_size())
    else: print("sd other", k, type(v).__name__)
# _packed_params storage via _weight_bias? maybe method exists only on the module not the params class; try:
for n,mod in m.named_modules():
    if hasattr(mod, "_packed_params"):
        pp = mod._packed_params
        try:
            qw, bias = pp._weight_bias()
            print("pw ok", n, tuple(qw.shape))
        except Exception as e:
            print("pw err", type(e).__name__)
            # try state_dict
            try:
                for k,v in pp.state_dict().items():
                    print("  pp sd", k, type(v).__name__, getattr(v,'shape',None))
            except Exception as e2:
                print("  pp sd err", e2)
EOF

