import io, zipfile, torch, pickle
torch.backends.quantized.engine = "qnnpack"
import warnings; warnings.filterwarnings("ignore")

# find the real C2 mlp int8_dynamic artifact bytes
import os
d = "results/precision_artifacts"
for f in sorted(os.listdir(d)):
    if f.startswith("mlp-int8_dynamic") and "20261110" in f:
        print("===", f, os.path.getsize(os.path.join(d,f)))
        path = os.path.join(d,f)
        payload = torch.load(path, weights_only=False)
        pickled = payload["state"]["pickled"]
        print("  pickled blob len:", len(pickled))
        z = zipfile.ZipFile(io.BytesIO(pickled))
        for i in z.infolist():
            if i.file_size: print(f"   {i.filename} {i.file_size}")
        pkl = z.read([n for n in z.namelist() if n.endswith("data.pkl")][0])
        print("  inner pkl len:", len(pkl))
        counts = {}
        class Pk(pickle.Unpickler):
            def persistent_load(self, pid):
                counts[pid[2]] = counts.get(pid[2], 0) + 1
                raise SystemExit
        try:
            Pk(io.BytesIO(pkl)).load()
        except SystemExit:
            pass
        print("  storage refs until first failure:", counts)
        print("  QInt8Storage refs:", pkl.count(b"QInt8Storage"))

