import warnings; warnings.filterwarnings("ignore")
from lab3 import precision as P
from lab3.evaln import load_checkpoint
import json
sel8 = json.load(open("results/int8_selection.json"))["selection"]

def dump(model, label):
    print("========", label)
    for n, mod in model.named_modules():
        print("  MOD", n or "<root>", type(mod).__name__)
    for n, p in model.named_parameters():
        print("  PARAM", n, p.dtype, tuple(p.shape), int(p.count_nonzero()))
    for n, b in model.named_buffers():
        print("  BUFFER", n, b.dtype, tuple(b.shape))
    sd = model.state_dict()
    for k, v in sd.items():
        if not torch.is_tensor(v):
            print("  SD-NON-TENSOR", k, type(v).__name__)
    for n, mod in model.named_modules():
        if type(mod).__name__ == "GraphModule":
            for attr in dir(mod):
                if "packed_weight" in attr or "scale" in attr or "zero_point" in attr:
                    try:
                        v = getattr(mod, attr)
                        print("  GM-ATTR", n, attr, type(v).__name__, getattr(v, "shape", None))
                    except Exception as e:
                        print("  GM-ATTR", n, attr, "ERR", str(e)[:80])
            print("  GM-state:", {k: (type(v).__name__, tuple(v.shape) if torch.is_tensor(v) else None) for k, v in mod.state_dict().items()})

for arch in ("mlp", "cnn", "gcn"):
    parent,_ = load_checkpoint(arch, 0); parent.eval()
    method = sel8[arch]["selected"]
    quant = P.int8_quantize_dynamic if method == "int8_dynamic" else P.int8_quantize_static
    m, _ = quant(parent, arch)
    dump(m, f"{arch} {method}")
    # also the other method for completeness
    quant2 = P.int8_quantize_dynamic if method == "int8_static" else P.int8_quantize_static
    m2, _ = quant2(parent, arch)
    dump(m2, f"{arch} {method if method=='int8_dynamic' else 'int8_dynamic'}-alt" if False else f"{arch} other={method if method=='int8_static' else 'int8_dynamic'}")
EOF
