import sys
sys.path.insert(0, "code")
import torch
torch.backends.quantized.engine = "qnnpack"
import warnings; warnings.filterwarnings("ignore")
from lab3 import precision as P
from lab3.evaln import load_checkpoint

def scan(model, label):
    print("=====", label, type(model).__name__)
    for n, mod in model.named_modules():
        # ScriptObject stored as a plain instance attribute
        for k in list(vars(mod)):
            v = getattr(mod, k)
            if isinstance(v, torch.ScriptObject):
                print(f"  {n or '<root>'} attr {k}: {type(v).__name__}")
        # children that are ScriptObject-holders
    # also scan non-registered attributes via state_dict
    sd = model.state_dict()
    for k, v in sd.items():
        if not torch.is_tensor(v):
            print("  SD:", k, type(v).__name__)

for arch in ("mlp", "cnn", "gcn"):
    parent,_ = load_checkpoint(arch, 0); parent.eval()
    for name, q in (("dyn", P.int8_quantize_dynamic), ("stat", P.int8_quantize_static)):
        m,_ = q(parent, arch)
        scan(m, f"{arch} {name}")
EOF
