for arch in ("mlp", "cnn", "gcn"):
    parent,_ = load_checkpoint(arch,0); parent.eval()
    for nm, q in (("dyn", P.int8_quantize_dynamic), ("stat", P.int8_quantize_static)):
        m,_ = q(parent, arch)
        dump(f"{arch} {nm}", m)
