"""C3: dump all per-module state (params, buffers, raw attrs, state_dict) for a
converted model so we can see exactly what bytes_by_dtype sees per module."""
import sys
sys.path.insert(0, "code")
import torch
torch.backends.quantized.engine = "qnnpack"
import warnings; warnings.filterwarnings("ignore")
from lab3 import precision as P
from lab3.evaln import load_checkpoint
import json
sel8 = json.load(open("results/int8_selection.json"))["selection"]

def dump(label, model):
    print("=====", label)
    for n, mod in model.named_modules():
        tag = n or "<root>"
        p = {k: v for k, v in mod.named_parameters(recurse=False)}
        b = {k: v for k, v in mod.named_buffers(recurse=False)}
        raw = {k: v for k, v in list(vars(mod).items())
               if (torch.is_tensor(v) or isinstance(v, torch.ScriptObject))
               and k not in p and k not in b}
        line = f"  MOD {tag} [{type(mod).__name__}]"
        if p or b or raw:
            line += "  params=" + {k: (str(v.dtype), tuple(v.shape)) for k, v in p.items()} \
                  + " buffers=" + {k: (str(v.dtype), tuple(v.shape)) for k, v in b.items()} \
                  + " raw=" + {k: type(v).__name__ for k, v in raw.items()}
        print(line)
    print("  --- full state_dict tensors ---")
    for k, v in model.state_dict().items():
        if torch.is_tensor(v):
            print(f"    {k} {v.dtype} {tuple(v.shape)} {v.numel()*v.element_size()}B")
        else:
            print(f"    {k} <{type(v).__name__}>")

