import sys
sys.path.insert(0, "code")
import torch
torch.backends.quantized.engine = "qnnpack"
import warnings; warnings.filterwarnings("ignore")
from lab3 import precision as P
from lab3.evaln import load_checkpoint
import json
sel = json.load(open("results/partc_selection.json"))

def dump(label, m):
    print("=====", label)
    for n, mod in m.named_modules():
        p = {k: v for k, v in mod.named_parameters(recurse=False)}
        b = {k: v for k, v in mod.named_buffers(recurse=False)}
        raw = {k: v for k, v in list(vars(mod).items())
               if (torch.is_tensor(v) or isinstance(v, torch.ScriptObject))
               and k not in p and k not in b}
        if p or b or raw:
            print(f"  {n or '<root>'} [{type(mod).__name__}] params={ {k:(str(v.dtype),tuple(v.shape)) for k,v in p.items()} } buffers={ {k:(str(v.dtype),tuple(v.shape)) for k,v in b.items()} } raw={ {k:type(v).__name__ for k,v in raw.items()} }")

for arch in ("mlp","cnn","gcn"):
    parent,_ = load_checkpoint(arch,0); parent.eval()
    m,_ = P.int8_quantize_dynamic(parent, arch)
    dump(f"{arch} DYN", m)
    m,_ = P.int8_quantize_static(parent, arch)
    dump(f"{arch} STAT", m)
EOF
